import type { FC } from 'react';
import { useEffect, useState } from 'react';
import { Download, Images } from 'lucide-react';
import { formatBytes } from '@/lib/image/convert';
import type { PdfPageImage } from '@/lib/pdf/convert';

interface ConversionResultProps {
  images: PdfPageImage[];
  zipBlob: Blob | null;
  fileBaseName: string;
  hasFile: boolean;
  progress: { page: number; total: number } | null;
  isZipping: boolean;
  error: string | null;
  onGenerate: () => void;
}

const PageThumb: FC<{ image: PdfPageImage }> = ({ image }) => {
  const [url, setUrl] = useState<string | null>(null);

  useEffect(() => {
    const objectUrl = URL.createObjectURL(image.blob);
    setUrl(objectUrl);
    return () => URL.revokeObjectURL(objectUrl);
  }, [image.blob]);

  return (
    <div className="rounded-lg overflow-hidden border border-border bg-background/50 aspect-[3/4]">
      {url && <img src={url} alt={`Page ${image.pageNumber}`} className="w-full h-full object-cover" />}
    </div>
  );
};

// Generation is explicit (a button), not reactive to every settings tweak —
// re-rendering every page is expensive, so it only runs once the user is
// done adjusting resolution/quality/page range and asks for it.
const ConversionResult: FC<ConversionResultProps> = ({
  images,
  zipBlob,
  fileBaseName,
  hasFile,
  progress,
  isZipping,
  error,
  onGenerate,
}) => {
  const handleDownload = () => {
    if (!zipBlob) return;
    const url = URL.createObjectURL(zipBlob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `${fileBaseName}-jpgs.zip`;
    document.body.appendChild(a);
    a.click();
    a.remove();
    URL.revokeObjectURL(url);
  };

  if (error) {
    return (
      <div className="glass-panel p-6 space-y-3">
        <p className="text-sm text-destructive" role="alert">
          {error}
        </p>
        <button
          type="button"
          onClick={onGenerate}
          className="inline-flex items-center justify-center gap-2 px-4 py-2.5 rounded-lg text-sm font-medium bg-accent text-accent-foreground hover:bg-accent/90 transition-colors"
        >
          <Images className="w-4 h-4" />
          Try again
        </button>
      </div>
    );
  }

  if (progress || isZipping) {
    const pct = progress ? Math.round((progress.page / progress.total) * 100) : 100;
    return (
      <div className="glass-panel p-6 space-y-3" role="status" aria-live="polite">
        <p className="text-sm text-muted-foreground">
          {isZipping
            ? 'Zipping pages…'
            : `Converting page ${progress?.page} of ${progress?.total}…`}
        </p>
        <div className="h-1.5 rounded-full bg-border overflow-hidden">
          <div
            className="h-full bg-accent transition-all duration-200"
            style={{ width: `${isZipping ? 100 : pct}%` }}
          />
        </div>
      </div>
    );
  }

  if (!hasFile) {
    return (
      <div className="glass-panel p-6 flex items-center justify-center text-sm text-muted-foreground min-h-[104px]">
        Upload a PDF to convert its pages to JPGs
      </div>
    );
  }

  if (!zipBlob) {
    return (
      <div className="glass-panel p-6 flex items-center justify-between gap-4 flex-wrap">
        <p className="text-sm text-muted-foreground">Set your options above, then generate.</p>
        <button
          type="button"
          onClick={onGenerate}
          className="inline-flex items-center justify-center gap-2 px-4 py-2.5 rounded-lg text-sm font-medium bg-accent text-accent-foreground hover:bg-accent/90 transition-colors"
        >
          <Images className="w-4 h-4" />
          Generate Images
        </button>
      </div>
    );
  }

  return (
    <div className="glass-panel hover:border-border p-4 md:p-6 space-y-4">
      <div className="flex items-center justify-between gap-4 flex-wrap">
        <p className="text-sm font-medium text-foreground">
          {images.length} {images.length === 1 ? 'page' : 'pages'} · {formatBytes(zipBlob.size)} zip
        </p>
        <button
          type="button"
          onClick={handleDownload}
          className="inline-flex items-center justify-center gap-2 px-4 py-2.5 rounded-lg text-sm font-medium bg-accent text-accent-foreground hover:bg-accent/90 transition-colors"
        >
          <Download className="w-4 h-4" />
          Download ZIP
        </button>
      </div>

      <div className="grid grid-cols-3 sm:grid-cols-4 md:grid-cols-5 gap-3">
        {images.map((image) => (
          <PageThumb key={image.pageNumber} image={image} />
        ))}
      </div>
    </div>
  );
};

export default ConversionResult;
